using System;using System.Collections;using System.Collections.Generic;using System.IO;using System.Linq;using System.Reflection;using System.Xml;
namespace OwnLabView {
internal static class BuildSpecs {
 internal static Dictionary<string,object>[] Parse(Dictionary<string,object> args,string[] members,ProjectSource source){
  if(args.ContainsKey("build")&&!(args["build"] is bool))throw new ArgumentException("build must be Boolean.");object[] raw;
  if(args.ContainsKey("build_specs"))raw=Data.Array(args["build_specs"]);else if(source!=null){var report=Data.Map(Data.Json.DeserializeObject(File.ReadAllText(source.ReportPath)));raw=report.ContainsKey("build_specs")?Data.Array(report["build_specs"]):new object[0];}else raw=new object[0];
  if(raw.Length>16)throw new ArgumentException("At most16 build specifications.");var names=new HashSet<string>(StringComparer.OrdinalIgnoreCase);var result=new List<Dictionary<string,object>>();foreach(var value in raw){var spec=Data.Map(value);Data.Keys(spec,"name","kind","source_path","output_name");string name=Data.Text(spec,"name"),kind=Data.Text(spec,"kind"),path=Data.Text(spec,"source_path");Storage.ArtifactFilename(name+".vi",".vi");if(!names.Add(name)||name.Length>40||!new[]{"EXE","DLL","SDIST"}.Contains(kind))throw new ArgumentException("Distinct build names and EXE/DLL/SDIST kind required.");if(!members.Contains(path,StringComparer.OrdinalIgnoreCase)||!Path.GetExtension(path).Equals(".vi",StringComparison.OrdinalIgnoreCase))throw new ArgumentException("Build source must be a requested VI project member.");GeneratedViDependency.ValidateOne(path);string output=spec.ContainsKey("output_name")?Data.Text(spec,"output_name"):name+(kind=="EXE"?".exe":kind=="DLL"?".dll":"");if(kind!="SDIST")Storage.ArtifactFilename(output,kind=="EXE"?".exe":".dll");else if(spec.ContainsKey("output_name"))throw new ArgumentException("SDIST has a directory destination; omit output_name.");var normalized=new Dictionary<string,object>{{"name",name},{"kind",kind},{"source_path",path}};if(kind!="SDIST")normalized["output_name"]=output;result.Add(normalized);}return result.ToArray();
 }
 static object Find(object parent,string path,List<object> refs){foreach(object item in (IEnumerable)LabView.Invoke(parent,"Children",BindingFlags.GetProperty)){refs.Add(item);string kind=Convert.ToString(LabView.Invoke(item,"TypeString",BindingFlags.GetProperty));if(kind=="Dependencies"||kind=="Build")continue;if(kind.IndexOf("Folder",StringComparison.OrdinalIgnoreCase)>=0){object found=Find(item,path,refs);if(found!=null)return found;}else if(String.Equals(TypeImport.NativePath(Convert.ToString(LabView.Invoke(item,"Path",BindingFlags.GetProperty))),path,StringComparison.OrdinalIgnoreCase))return item;}return null;}
 internal static object[] Apply(object app,object computer,List<object> refs,string project,Dictionary<string,object>[] specs,bool build){var result=new List<object>();var seen=new HashSet<string>(StringComparer.OrdinalIgnoreCase);var hashes=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase);foreach(var spec in specs){string name=Data.Text(spec,"name"),kind=Data.Text(spec,"kind"),destination=Path.Combine(Path.GetDirectoryName(project),"builds",name);if(Directory.Exists(destination))throw new IOException("Build destination already exists.");Directory.CreateDirectory(destination);object item=Find(computer,Data.Text(spec,"source_path"),refs);if(item==null)throw new IOException("Native build source item absent.");object helper=ClassArtifacts.OpenAuxiliary(app,refs,"OwnBuild20261013_Create"+kind+".vi",seen,hashes);foreach(var pair in new Dictionary<string,object>{{"Project Path",project},{"Save Project Path",project},{"Member ID",LabView.Invoke(item,"ItemID",BindingFlags.GetProperty)},{"Spec Name",name},{"Destination",destination}})LabView.Invoke(helper,"SetControlValue",BindingFlags.InvokeMethod,pair.Key,pair.Value);if(kind!="SDIST")LabView.Invoke(helper,"SetControlValue",BindingFlags.InvokeMethod,"Output Name",spec["output_name"]);LabView.Invoke(helper,"Run",BindingFlags.InvokeMethod,false);ClassArtifacts.CheckError(helper);
  var files=new List<object>();if(build){string native=Path.Combine(Path.GetDirectoryName(LabView.RegisteredExecutable()),@"vi.lib\AppBuilder\BuildTargetBuildSpecification.vi");object runner=LabView.Invoke(app,"GetVIReference",BindingFlags.InvokeMethod,native,"",false,0);refs.Add(runner);LabView.Invoke(runner,"SetControlValue",BindingFlags.InvokeMethod,"Path to project",project);LabView.Invoke(runner,"SetControlValue",BindingFlags.InvokeMethod,"Name of build specification (if empty: build all)",name);LabView.Invoke(runner,"Run",BindingFlags.InvokeMethod,false);ClassArtifacts.CheckError(runner);foreach(string raw in ((IEnumerable)LabView.Invoke(runner,"GetControlValue",BindingFlags.InvokeMethod,"Generated files")).Cast<object>().Select(Convert.ToString)){string path=TypeImport.NativePath(raw);if(!path.StartsWith(destination+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase)||!File.Exists(path))throw new IOException("Built output missing or outside isolated destination: "+path);Storage.NoReparse(path);files.Add(new{path,sha256=Data.Hash(path),bytes=new FileInfo(path).Length});}if(files.Count==0)throw new IOException("NI build returned no files.");if(kind!="SDIST"&&!File.Exists(Path.Combine(destination,Data.Text(spec,"output_name"))))throw new IOException("Expected binary output missing.");}
  result.Add(new{name,kind,destination,created=true,built=build,files=files.ToArray()});}
 return result.ToArray();}
}
}
